package cn.ping.launcher;
import android.app.*;import android.os.*;import android.content.*;import java.util.*;
public class ReleaseTest extends Instrumentation {
 void snapshot(Activity a,String file){try{android.view.View view=a.getWindow().getDecorView();android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(view.getWidth(),view.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);view.draw(new android.graphics.Canvas(image));java.io.FileOutputStream stream=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),file));image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);stream.close();image.recycle();}catch(Exception e){throw new RuntimeException(e);}}
 Map<String,?> original;android.content.SharedPreferences vault;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onStart(){Bundle output=new Bundle();try{vault=getTargetContext().getSharedPreferences("vault",0);original=new HashMap<>(vault.getAll());String pin="638291";HiddenVault.set(getTargetContext(),pin);String first=vault.getString("hash","");check(HiddenVault.verify(getTargetContext(),pin),"correct password");check(!HiddenVault.verify(getTargetContext(),"999999"),"wrong password");HiddenVault.set(getTargetContext(),pin);check(!first.equals(vault.getString("hash","")),"random salt");String token=HiddenVault.grant();check(HiddenVault.consume(token),"token");check(!HiddenVault.consume(token),"token replay");
 MainActivity home=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(700);runOnMainSync(()->{check(home.pager.getChildCount()==home.occupiedPages(),"no trailing blank page");home.pager.go(home.pager.getChildCount()-1,false);home.dragging=home.apps.get(0).id;home.edge=1;home.edgeTurn.run();home.handler.removeCallbacks(home.edgeTurn);check(home.pager.getChildCount()==home.occupiedPages()+1,"temporary drag page");home.dragging=null;home.edge=0;home.render();check(home.pager.getChildCount()==home.occupiedPages(),"cancel removes blank page");});
 HiddenGateActivity gate=(HiddenGateActivity)startActivitySync(new Intent(getTargetContext(),HiddenGateActivity.class).putExtra("quick",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->{snapshot(gate,"gate-preview.png");for(char digit:"999999".toCharArray())gate.digit(String.valueOf(digit));});Thread.sleep(700);check(gate.stage==0&&!gate.isFinishing(),"wrong password remains locked");ActivityMonitor monitor=addMonitor(HiddenAppsActivity.class.getName(),null,false);runOnMainSync(()->{for(char digit:pin.toCharArray())gate.digit(String.valueOf(digit));});Activity quick=monitor.waitForActivityWithTimeout(4000);check(quick!=null,"correct password opens hidden apps");check(quick.getIntent().getBooleanExtra("quick",false),"quick launch mode");Thread.sleep(700);runOnMainSync(()->snapshot(quick,"hidden-preview.png"));output.putString("result","PASS: password hash/salt, wrong/correct PIN, token replay, trailing page removal and temporary drag page");finish(0,output);
 }catch(Throwable e){output.putString("error",e.toString());finish(1,output);}finally{if(vault!=null&&original!=null){android.content.SharedPreferences.Editor editor=vault.edit().clear();for(Map.Entry<String,?> e:original.entrySet()){Object v=e.getValue();if(v instanceof String)editor.putString(e.getKey(),(String)v);else if(v instanceof Integer)editor.putInt(e.getKey(),(Integer)v);else if(v instanceof Long)editor.putLong(e.getKey(),(Long)v);}editor.commit();}}}
}
